mapper.select:
select rule.clean_fields, rule.mapping_field, rule.is_mapping, rule.mapping_rule, rule.level, rule.parent_path
from b_marketing_data_clean_general_rule_config rule
inner join b_marketing_data_clean_general_config config on config.id = rule.clean_config_id
where config.api_code = #{apiCode}
and config.system_type = #{systemType}
and config.data_type = #{dataType}
and config.accept_type = #{acceptType}

    AND status=#{status}

and rule.is_del = 1
